// Только просмотр (без @data): «המלצות אחרונות» QA-R2-1 у родителя на iPhone (проект iphone, WebKit 375 — строже, чем 390 из проверки).
// Не прогонять при записи — запуск только по /qa-regress.
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { expectInsideViewport, expectNoHorizontalScroll } from '../placement-reading/reading.helpers';
import { T, openParentRecent, recentRows } from './review-request-marking.helpers';

test.use({ storageState: path.resolve(__dirname, '../../../auth/parent.json') });

const STATUS = new RegExp(`${T.markChild}|(^|[•·]\\s*)${T.markReview}(\\s*[•·]|$)`);

test.describe('Пометка ребёнка «לבקש בדיקה» у родителя — телефон (autotest-writer)', () => {
  test('Телефон: метки «הילד ביקש לבדוק» / «בבדיקה» внутри карточки, без горизонтальной прокрутки @iphone @prod-safe #37cdff', async ({ page }) => {
    await openParentRecent(page);
    await expectNoHorizontalScroll(page, '«המלצות אחרונות»');

    const rows = recentRows(page).filter({ hasText: STATUS });
    await expect(rows.first(), 'у QA-R2-1 нет рекомендаций с меткой — нужна пометка ребёнка или запрос (данные)').toBeVisible();
    const n = await rows.count();
    for (let i = 0; i < n; i++) {
      const row = rows.nth(i);
      const label = row.getByText(STATUS).first();
      const rb = await row.boundingBox();
      const lb = await label.boundingBox();
      expect(rb && lb, `строка ${i + 1}: нет boundingBox`).toBeTruthy();
      // Метка в пределах карточки (RM-06)
      expect(lb!.x, `строка ${i + 1}: метка левее карточки`).toBeGreaterThanOrEqual(rb!.x - 1);
      expect(lb!.x + lb!.width, `строка ${i + 1}: метка правее карточки`).toBeLessThanOrEqual(rb!.x + rb!.width + 1);
      await expectInsideViewport(page, label, `строка ${i + 1}: метка`);
    }

    // «למה זה הומלץ» первой помеченной рекомендации: кнопка (если запрос ещё не открыт) — в пределах экрана
    await rows.first().click();
    const openBtn = page.getByRole('button', { name: T.openReview }).filter({ visible: true });
    await expect(page.getByText(STATUS).filter({ visible: true }).first()).toBeVisible();
    if ((await openBtn.count()) > 0) await expectInsideViewport(page, openBtn.first(), '«פתיחת בקשת בדיקה»');
    await expectNoHorizontalScroll(page, '«למה זה הומלץ»');
  });
});
